mapper.update:
update my_mall.shopping_cart


        goods_count=#{goodsCount},


        update_time=#{updateTime}


where id=#{id}

mapper.delete:
DELETE FROM my_mall.shopping_cart
WHERE id IN

    #{id}

AND user_id = #{userId}

mapper.select:
select sc.goods_id as goodsId, g.name as goodsName, g.cover_img as coverImg, g.selling_price as price, sc.goods_count as count from my_mall.shopping_cart as sc left join my_mall.goods as g on sc.goods_id=g.id where sc.id in
#{id}
and sc.user_id = #{userId}
